            command.add("-s");
            command.add(template.getResolution());
        }
        if (task.getWatermarkContent() != null && !task.getWatermarkContent().isEmpty()) {
            command.add("-vf");
            command.add(watermarkFilter(task));
        }
        command.add(task.getOutputFile());
        return command;
    }

    private String videoCodec(Template template) {
        if (template != null && "h265".equalsIgnoreCase(template.getCodec())) {
            return "libx265";
        }
        return "libx264";
    }

